TAX_VERIFICATION_SQLITE_SCHEMA=r'''
CREATE TABLE tax_verifications(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,jurisdiction TEXT NOT NULL,rules_version TEXT NOT NULL,professional TEXT NOT NULL,credentials TEXT NOT NULL,verified_on TEXT NOT NULL,effective_from TEXT NOT NULL,effective_to TEXT,registration_scope TEXT NOT NULL,supply_scope TEXT NOT NULL,item_classification_basis TEXT NOT NULL,price_basis TEXT NOT NULL CHECK(price_basis IN ('inclusive','exclusive')),rounding_basis TEXT NOT NULL,source_urls_json TEXT NOT NULL,limitations TEXT NOT NULL,attestation_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','superseded','revoked')),created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,jurisdiction,rules_version));
'''
